    internal const string TemporalVisibilityReleasesGlsl = @"
// THE SHIPPED DECISION, generated by TemporalVisibilityFastPath. Edit the generator, never this text. The call site
// ignores the path bits, which tell the equivalence oracle which path ran and whether a change was computed.
const uint VisibilityFastPath = 1u, VisibilitySlowPath = 2u, VisibilityRangeSkip = 4u, VisibilityChangeComputed = 8u,
    VisibilitySlowBinade = 16u;
// Below this distance from both ends of the block's range no history mean can lie 0.1 from the current mean.
const float VisibilityRangeSkipMargin = VisibilityReleaseThreshold - 1.220703125e-4;

// A column or row that is a power of two, where (at + 0.5) - J and (at - J) + 0.5 can round apart under positive
// jitter. TemporalVisibilityFastPath.SlowForBinade states the proof.
bool temporalVisibilityPowerOfTwo(int at) { return at > 0 && (at & (at - 1)) == 0; }

// D's decision. Where the nine footprints form one 4x4 block inside the texture, the block is read once and every
// acceptance, weight and sum follows D's order and arithmetic, with the current acceptances from currentMask, the
// centre's temporalVisibilityCurrentMask. Anywhere else D's function runs as it shipped.
bool temporalVisibilityReleases(vec2 uv, ivec2 centre, ivec2 last, vec2 previousUv, float expectedDepth,
    uint currentMask, out float signedChange, out uint path) {
    signedChange = 0.0;
    // D's position chain is componentwise, so the diagonal neighbour (k, k) carries column k's x and row k's y.
    ivec2 at0 = clamp(centre + ivec2(-1, -1), ivec2(0), last);
    vec2 historyUv0 = previousUv + (vec2(at0) + 0.5 - Jitter.xy) / Sizes.xy
        - uv + PreviousJitter.xy / Sizes.xy;
    vec2 position0 = fma(historyUv0, Sizes.xy, vec2(-0.5));
    ivec2 base0 = ivec2(floor(position0));
    vec2 fraction0 = position0 - vec2(base0);
    ivec2 at1 = clamp(centre + ivec2(0, 0), ivec2(0), last);
    vec2 historyUv1 = previousUv + (vec2(at1) + 0.5 - Jitter.xy) / Sizes.xy
        - uv + PreviousJitter.xy / Sizes.xy;
    vec2 position1 = fma(historyUv1, Sizes.xy, vec2(-0.5));
    ivec2 base1 = ivec2(floor(position1));
    vec2 fraction1 = position1 - vec2(base1);
    ivec2 at2 = clamp(centre + ivec2(1, 1), ivec2(0), last);
    vec2 historyUv2 = previousUv + (vec2(at2) + 0.5 - Jitter.xy) / Sizes.xy
        - uv + PreviousJitter.xy / Sizes.xy;
    vec2 position2 = fma(historyUv2, Sizes.xy, vec2(-0.5));
    ivec2 base2 = ivec2(floor(position2));
    vec2 fraction2 = position2 - vec2(base2);
    // Consecutive bases on both axes, and the block inside the texture so that no corner clamps. An edge centre
    // fails the first test, because its clamped neighbour repeats the centre's chain.
    bool blockFits = base0 == base1 - 1 && base2 == base1 + 1 && all(greaterThanEqual(base1, ivec2(1)))
        && all(lessThanEqual(base1, last - 2));
    // FXC may compile these chains and D's in different association orders, which round apart only at a column or
    // row that is a power of two under positive jitter on its axis. Such a block takes D's path.
    bool binade = floatBitsToInt(Jitter.x) > 0 && (temporalVisibilityPowerOfTwo(at0.x)
            || temporalVisibilityPowerOfTwo(at1.x) || temporalVisibilityPowerOfTwo(at2.x))
        || floatBitsToInt(Jitter.y) > 0 && (temporalVisibilityPowerOfTwo(at0.y)
            || temporalVisibilityPowerOfTwo(at1.y) || temporalVisibilityPowerOfTwo(at2.y));
    if (!blockFits || binade) {
        path = VisibilitySlowPath | (blockFits ? VisibilitySlowBinade : 0u);
        bool valid = temporalVisibilityChange(uv, centre, last, previousUv, expectedDepth, signedChange);
        if (valid) path |= VisibilityChangeComputed;
        return valid && abs(signedChange) > VisibilityReleaseThreshold;
    }
    path = VisibilityFastPath;

    // R5: gather at integer texel corners, half a texel from any footprint-selection boundary. Coordinates use each
    // texture's actual size. For a 2x2 with low corner o, sample (o + 1) / textureSize. Components are x (0,1),
    // y (1,1), z (1,0), w (0,0), with row 1 at higher V. TemporalVisibilityGatherGpuTests compares every component
    // with Load bits, including R32F NaN payloads and every R8 value, on each backend. Only the source of each value
    // changes below. D's weights, accumulation order and fma pattern stay as written.
    // The current 3x3 uses four overlapping 2x2 quads inside at0..at2. No extra texel beyond that footprint is read,
    // so a centre one texel from any edge needs no stronger precondition. History uses four disjoint 2x2 quads.
    vec2 currentSize = vec2(textureSize(sampler2D(KeyShadowVisibility, LinearClamp), 0));
    vec4 currentGather00 = textureGather(sampler2D(KeyShadowVisibility, LinearClamp), vec2(at0 + ivec2(1, 1)) / currentSize, 0);
    vec4 currentGather10 = textureGather(sampler2D(KeyShadowVisibility, LinearClamp), vec2(at0 + ivec2(2, 1)) / currentSize, 0);
    vec4 currentGather01 = textureGather(sampler2D(KeyShadowVisibility, LinearClamp), vec2(at0 + ivec2(1, 2)) / currentSize, 0);
    vec4 currentGather11 = textureGather(sampler2D(KeyShadowVisibility, LinearClamp), vec2(at0 + ivec2(2, 2)) / currentSize, 0);
    float current0 = currentGather00.w;
    float current1 = currentGather00.z;
    float current2 = currentGather10.z;
    float current3 = currentGather00.x;
    float current4 = currentGather00.y;
    float current5 = currentGather10.y;
    float current6 = currentGather01.x;
    float current7 = currentGather01.y;
    float current8 = currentGather11.y;
    ivec2 block = base1 - 1;
    vec2 previousSize = vec2(textureSize(sampler2D(PreviousKeyShadowVisibility, LinearClamp), 0));
    vec4 previousGather00 = textureGather(sampler2D(PreviousKeyShadowVisibility, LinearClamp), vec2(block + ivec2(1, 1)) / previousSize, 0);
    vec4 previousGather10 = textureGather(sampler2D(PreviousKeyShadowVisibility, LinearClamp), vec2(block + ivec2(3, 1)) / previousSize, 0);
    vec4 previousGather01 = textureGather(sampler2D(PreviousKeyShadowVisibility, LinearClamp), vec2(block + ivec2(1, 3)) / previousSize, 0);
    vec4 previousGather11 = textureGather(sampler2D(PreviousKeyShadowVisibility, LinearClamp), vec2(block + ivec2(3, 3)) / previousSize, 0);
    float previous00 = previousGather00.w;
    float previous10 = previousGather00.z;
    float previous20 = previousGather10.w;
    float previous30 = previousGather10.z;
    float previous01 = previousGather00.x;
    float previous11 = previousGather00.y;
    float previous21 = previousGather10.x;
    float previous31 = previousGather10.y;
    float previous02 = previousGather01.w;
    float previous12 = previousGather01.z;
    float previous22 = previousGather11.w;
    float previous32 = previousGather11.z;
    float previous03 = previousGather01.x;
    float previous13 = previousGather01.y;
    float previous23 = previousGather11.x;
    float previous33 = previousGather11.y;
    if ((currentMask & VisibilityCentreFinite) == 0u || !temporalVisibilityFiniteDepth(expectedDepth)) return false;
    float previousTolerance = VisibilityDepthTolerance * max(expectedDepth, 1.0e-5);

    // D's current rejection of each texel, from the mask, then its sum and count in D's order.
    bool accepted0 = (currentMask & 1u) != 0u;
    bool accepted1 = (currentMask & 2u) != 0u;
    bool accepted2 = (currentMask & 4u) != 0u;
    bool accepted3 = (currentMask & 8u) != 0u;
    bool accepted4 = (currentMask & 16u) != 0u;
    bool accepted5 = (currentMask & 32u) != 0u;
    bool accepted6 = (currentMask & 64u) != 0u;
    bool accepted7 = (currentMask & 128u) != 0u;
    bool accepted8 = (currentMask & 256u) != 0u;
    float currentSum = 0.0;
    float currentCount = 0.0;
    if (accepted0) { currentSum += current0; currentCount += 1.0; }
    if (accepted1) { currentSum += current1; currentCount += 1.0; }
    if (accepted2) { currentSum += current2; currentCount += 1.0; }
    if (accepted3) { currentSum += current3; currentCount += 1.0; }
    if (accepted4) { currentSum += current4; currentCount += 1.0; }
    if (accepted5) { currentSum += current5; currentCount += 1.0; }
    if (accepted6) { currentSum += current6; currentCount += 1.0; }
    if (accepted7) { currentSum += current7; currentCount += 1.0; }
    if (accepted8) { currentSum += current8; currentCount += 1.0; }
    if (!(currentCount > 0.0)) return false;

    // R4: the history mean lies in the block's range, so a current mean this near both ends cannot release. The
    // test is taken on the sum and the count, the mean's distances times the count: a second use of the current
    // mean changed how Metal compiles D's own change below by an ulp.
    float lowest0 = min(min(previous00, previous10), min(previous20, previous30));
    float lowest1 = min(min(previous01, previous11), min(previous21, previous31));
    float lowest2 = min(min(previous02, previous12), min(previous22, previous32));
    float lowest3 = min(min(previous03, previous13), min(previous23, previous33));
    float lowest = min(min(lowest0, lowest1), min(lowest2, lowest3));
    float highest0 = max(max(previous00, previous10), max(previous20, previous30));
    float highest1 = max(max(previous01, previous11), max(previous21, previous31));
    float highest2 = max(max(previous02, previous12), max(previous22, previous32));
    float highest3 = max(max(previous03, previous13), max(previous23, previous33));
    float highest = max(max(highest0, highest1), max(highest2, highest3));
    if (max(currentSum - lowest * currentCount, highest * currentCount - currentSum)
        <= VisibilityRangeSkipMargin * currentCount) {
        path |= VisibilityRangeSkip;
        return false;
    }

    // D's history rejection, once a block texel, then D's 36 bilinear terms in D's order.
    vec2 storedSize = vec2(textureSize(sampler2D(PrevDepth, LinearClamp), 0));
    vec4 storedGather00 = textureGather(sampler2D(PrevDepth, LinearClamp), vec2(block + ivec2(1, 1)) / storedSize, 0);
    vec4 storedGather10 = textureGather(sampler2D(PrevDepth, LinearClamp), vec2(block + ivec2(3, 1)) / storedSize, 0);
    vec4 storedGather01 = textureGather(sampler2D(PrevDepth, LinearClamp), vec2(block + ivec2(1, 3)) / storedSize, 0);
    vec4 storedGather11 = textureGather(sampler2D(PrevDepth, LinearClamp), vec2(block + ivec2(3, 3)) / storedSize, 0);
    float stored00 = storedGather00.w;
    float stored10 = storedGather00.z;
    float stored20 = storedGather10.w;
    float stored30 = storedGather10.z;
    float stored01 = storedGather00.x;
    float stored11 = storedGather00.y;
    float stored21 = storedGather10.x;
    float stored31 = storedGather10.y;
    float stored02 = storedGather01.w;
    float stored12 = storedGather01.z;
    float stored22 = storedGather11.w;
    float stored32 = storedGather11.z;
    float stored03 = storedGather01.x;
    float stored13 = storedGather01.y;
    float stored23 = storedGather11.x;
    float stored33 = storedGather11.y;
    bool held00 = temporalVisibilityFiniteDepth(stored00) && abs(stored00 - expectedDepth) <= previousTolerance;
    bool held10 = temporalVisibilityFiniteDepth(stored10) && abs(stored10 - expectedDepth) <= previousTolerance;
    bool held20 = temporalVisibilityFiniteDepth(stored20) && abs(stored20 - expectedDepth) <= previousTolerance;
    bool held30 = temporalVisibilityFiniteDepth(stored30) && abs(stored30 - expectedDepth) <= previousTolerance;
    bool held01 = temporalVisibilityFiniteDepth(stored01) && abs(stored01 - expectedDepth) <= previousTolerance;
    bool held11 = temporalVisibilityFiniteDepth(stored11) && abs(stored11 - expectedDepth) <= previousTolerance;
    bool held21 = temporalVisibilityFiniteDepth(stored21) && abs(stored21 - expectedDepth) <= previousTolerance;
    bool held31 = temporalVisibilityFiniteDepth(stored31) && abs(stored31 - expectedDepth) <= previousTolerance;
    bool held02 = temporalVisibilityFiniteDepth(stored02) && abs(stored02 - expectedDepth) <= previousTolerance;
    bool held12 = temporalVisibilityFiniteDepth(stored12) && abs(stored12 - expectedDepth) <= previousTolerance;
    bool held22 = temporalVisibilityFiniteDepth(stored22) && abs(stored22 - expectedDepth) <= previousTolerance;
    bool held32 = temporalVisibilityFiniteDepth(stored32) && abs(stored32 - expectedDepth) <= previousTolerance;
    bool held03 = temporalVisibilityFiniteDepth(stored03) && abs(stored03 - expectedDepth) <= previousTolerance;
    bool held13 = temporalVisibilityFiniteDepth(stored13) && abs(stored13 - expectedDepth) <= previousTolerance;
    bool held23 = temporalVisibilityFiniteDepth(stored23) && abs(stored23 - expectedDepth) <= previousTolerance;
    bool held33 = temporalVisibilityFiniteDepth(stored33) && abs(stored33 - expectedDepth) <= previousTolerance;
    float columnNear0 = 1.0 - fraction0.x;
    float rowNear0 = 1.0 - fraction0.y;
    float columnNear1 = 1.0 - fraction1.x;
    float rowNear1 = 1.0 - fraction1.y;
    float columnNear2 = 1.0 - fraction2.x;
    float rowNear2 = 1.0 - fraction2.y;
